"""Generic tools for a research agent that works websites in a browser: read pages, read many pages of one kind,
and record evidence as it goes. An MCP server (stdio) next to Playwright MCP, attached to the same browser over CDP.

Nothing here knows a website: no addresses, selectors or words of any site. The model chooses every page; the tools
only read what it chose (the rendered page, as a user sees it), page through what it asked for, and check records.

Environment:
  CDP_URL         the browser Playwright MCP works in
  SITES_JSON      [{"siteId": ..., "url": ...}] from the run's access list
  EVIDENCE_DIR    folder with evidence.py and resolver.py (the agent's own copies)
  STORE_PATH      JSON file the evidence is saved to after every change
"""
from __future__ import annotations

import asyncio
import difflib
import functools
import json
import os
import re
import sys
import time
import typing
from collections import Counter, defaultdict
from decimal import Decimal, InvalidOperation
from pathlib import Path
from urllib.parse import quote, unquote, urljoin, urlparse

sys.path.insert(0, os.environ.get("EVIDENCE_DIR", "."))

from mcp.server.mcpserver import MCPServer  # noqa: E402
from playwright.async_api import async_playwright  # noqa: E402
from pydantic import BaseModel, ValidationError  # noqa: E402

import evidence as ev  # noqa: E402
from resolver import resolve  # noqa: E402

SITES = {s["siteId"]: s["url"].rstrip("/") for s in json.loads(os.environ.get("SITES_JSON", "[]"))}
STORE = Path(os.environ.get("STORE_PATH", "evidence.json"))
PAGE_CHARS = 7000          # per page returned to the model
PARALLEL = 4               # background tabs per site at once
NAV_TIMEOUT_MS = 15000

server = MCPServer("web", instructions="Read pages the agent chose and record evidence.")

# --- browser ---------------------------------------------------------------------------------------------------------

_pw = _browser = None
visited: dict[str, set[str]] = defaultdict(set)      # site -> URLs a tab showed (clicked to or read)
boiler: dict[str, Counter] = defaultdict(Counter)   # site -> short no-digit line -> on how many pages
boiler_seen: dict[str, set[tuple[str, str]]] = defaultdict(set)
_sem: dict[str, asyncio.Semaphore] = {}

ZERO_WIDTH = dict.fromkeys(map(ord, "​‌‍⁠﻿­"))
# Numbers the page marks with their format, e.g. "12,345 (en-US)" or "1.234,56 (de-DE)": converted to plain numbers.
MARKED = re.compile(r"(?<![\w.,])(\d{1,3}(?:[.,  ' ]\d{3})+(?:[.,]\d+)?|\d+(?:[.,]\d+)?)"
                    r"\s*\(([a-z]{2})(?:[-_][A-Za-z]{2})?\)")
COMMA_DECIMAL = {"de", "fr", "es", "it", "nl", "pt", "pl", "cs", "sk", "da", "sv", "nb", "no", "fi", "ru", "tr",
                 "hu", "ro", "el", "id", "vi", "uk", "hr", "sl", "lt", "lv", "et", "bg", "sr"}

async def browser():
    global _pw, _browser
    if _browser is None or not _browser.is_connected():
        _pw = _pw or await async_playwright().start()
        _browser = await _pw.chromium.connect_over_cdp(os.environ["CDP_URL"])
        for context in _browser.contexts:
            context.on("page", track)
            for page in context.pages:
                track(page)
                site = site_of(page.url)
                if site:
                    visited[site].add(clean_url(page.url))
    return _browser


async def site_page(site: str):
    """The site's tab the agent works in: the most recently opened tab showing that site."""
    b = await browser()
    pages = [p for c in b.contexts for p in c.pages if site_of(p.url) == site]
    if not pages:
        raise LookupError(f"No tab shows {site} yet: open it and log in in the browser first.")
    return pages[-1]


def clean_url(url: str) -> str:
    return url.replace("&amp;", "&").split("#")[0]


def plain_number(raw: str, lang: str) -> str:
    digits = re.sub(r"[  ' ]", "", raw)
    if lang in COMMA_DECIMAL:
        return digits.replace(".", "").replace(",", ".")
    return digits.replace(",", "")


def normalize(text: str) -> str:
    return MARKED.sub(lambda m: plain_number(m.group(1), m.group(2).lower()), text)


EXTRACT_JS = r"""() => {
  const vis = (e) => { const s = getComputedStyle(e); const r = e.getBoundingClientRect();
    return s.display !== 'none' && s.visibility !== 'hidden' && s.opacity !== '0' && (r.width > 0 || r.height > 0); };
  const imgs = [...document.querySelectorAll('img[alt],[role=img][aria-label],canvas[aria-label],[title]')]
    .filter(e => vis(e) && (e.getAttribute('alt') || e.getAttribute('aria-label') || (e.tagName === 'IMG' || e.tagName === 'CANVAS') && e.getAttribute('title')))
    .map(e => (e.getAttribute('alt') || e.getAttribute('aria-label') || e.getAttribute('title') || '').trim())
    .filter(Boolean);
  const links = [...document.querySelectorAll('a[href]')].filter(vis).map(a => ({
    text: (a.innerText || a.getAttribute('aria-label') || a.getAttribute('title') || '').replace(/\s+/g, ' ').trim(),
    href: a.href})).filter(l => l.href.startsWith('http'));
  return {url: location.href, title: document.title, text: document.body ? document.body.innerText : '',
          password: !!document.querySelector('input[type=password]'), images: [...new Set(imgs)].slice(0, 40), links};
}"""


async def extract(page) -> dict:
    """The page as a user sees it: visible text of the page and its frames, image labels, links."""
    data = await page.main_frame.evaluate(EXTRACT_JS)
    for frame in page.frames[1:]:
        try:
            sub = await asyncio.wait_for(frame.evaluate(EXTRACT_JS), 5)
        except Exception:
            continue
        if sub.get("text", "").strip():
            data["text"] += f"\n[frame {sub['url']}]\n" + sub["text"]
            data["images"] += sub["images"]
            data["links"] += sub["links"]
            data["password"] = data["password"] or sub["password"]
    return data


async def render(site: str, url: str) -> dict:
    """Open `url` in a background tab of the site's browser context (shares the login), read it, close the tab."""
    sem = _sem.setdefault(site, asyncio.Semaphore(PARALLEL))
    async with sem:
        context = (await site_page(site)).context
        page = await context.new_page()
        try:
            status = None
            for attempt in range(3):
                try:
                    response = await page.goto(url, wait_until="commit", timeout=NAV_TIMEOUT_MS)
                    status = response.status if response else None
                except Exception as error:  # noqa: BLE001
                    if attempt == 2:
                        return {"url": url, "error": str(error).splitlines()[0][:200]}
                    await asyncio.sleep(1 + attempt)
                    continue
                try:
                    await page.wait_for_load_state("domcontentloaded", timeout=8000)
                except Exception:  # noqa: BLE001 - a page that never finishes loading is still read
                    pass
                await page.wait_for_timeout(600)
                if status in (429, 502, 503, 504) and attempt < 2:
                    await asyncio.sleep(1.5 * (attempt + 1))
                    continue
                break
            data = await extract(page)
            data["status"] = status
            visited[site].add(clean_url(url))
            return data
        finally:
            await page.close()


def compact(site: str, data: dict, offset: int = 0, links: bool = False) -> str:
    """The text for the model: zero-width characters gone, marked numbers plain, the site's navigation chrome
    (short lines without digits seen on 3+ pages) dropped after it was shown, at most PAGE_CHARS characters."""
    url = clean_url(data.get("url", ""))
    lines = []
    for line in normalize(data.get("text", "").translate(ZERO_WIDTH)).splitlines():
        line = re.sub(r"[ \t]+", " ", line.replace("\t", " | ")).strip()
        if not line:
            continue
        if len(line) < 60 and not re.search(r"\d", line):
            if (line, url) not in boiler_seen[site]:
                boiler_seen[site].add((line, url))
                boiler[site][line] += 1
            if boiler[site][line] > 3:
                continue
        lines.append(line)
    text = "\n".join(lines)
    if data.get("images"):
        text += "\n[images: " + " | ".join(normalize(i.translate(ZERO_WIDTH)) for i in data["images"]) + "]"
    if data.get("password"):
        text = "[this page has a password field: a login page, or the session expired]\n" + text
    more = ""
    if len(text) > offset + PAGE_CHARS:
        more = f"\n[... {len(text) - offset - PAGE_CHARS} more characters: read again with offset={offset + PAGE_CHARS}]"
    text = text[offset:offset + PAGE_CHARS] + more
    if links:
        base = SITES.get(site, "")
        seen, rows = set(), []
        for l in data.get("links", []):
            href = clean_url(l["href"])
            if site_of(href) != site or href in seen or not l["text"]:
                continue
            seen.add(href)
            rows.append(f"{l['text'][:60]} -> {href[len(base):] if base and href.startswith(base) else href}")
        text += "\n[links]\n" + "\n".join(rows[:80])
    return f"## {url}\n{text}"


def guard(seconds: float):
    def wrap(fn):
        @functools.wraps(fn)
        async def inner(*args, **kwargs):
            try:
                return await asyncio.wait_for(fn(*args, **kwargs), seconds)
            except asyncio.TimeoutError:
                return f"FAILED: no result within {seconds:.0f} s"
            except LookupError as error:
                return f"FAILED: {error}"
            except Exception as error:  # noqa: BLE001 - a tool answers, it never crashes the session
                return f"FAILED: {type(error).__name__}: {str(error).splitlines()[0][:200] if str(error) else ''}"
        return inner
    return wrap


@server.tool()
@guard(60)
async def read(site: str, url: str = "", offset: int = 0, links: bool = False, urls: list[str] | None = None) -> str:
    """Read a page as text, the way a user sees it: visible text of the page and its frames, image labels,
    numbers that carry a format marker such as "1,234.5 (en-US)" already converted to plain numbers. Much cheaper
    than a browser snapshot when you need the content of a page rather than its controls.
    - url empty: the page currently shown in that site's tab (after you clicked there).
    - url given: that page, opened in a background tab of the same login (a page you saw a link to). Never use it for
      forms, searches that need a button, or anything that saves, confirms or sends.
    - urls: several pages you saw links to, read at once in background tabs (at most 20) - one call instead of many.
    - links=true also lists the page's links (text -> address). offset reads on in a long page."""
    if urls:
        targets = [clean_url(urljoin(SITES.get(site, "") + "/", u)) for u in urls[:20]]
        results = await asyncio.gather(*(render(site, u) for u in targets))
        out = []
        for u, data in zip(targets, results):
            if data.get("error"):
                out.append(f"## {u}\nFAILED: {data['error']} - open it by clicking instead")
            else:
                out.append(compact(site, data, 0, links))
        return "\n\n".join(out)
    if url:
        url = clean_url(urljoin(SITES.get(site, "") + "/", url))
        data = await render(site, url)
        if data.get("error"):
            return f"FAILED: {data['error']} - open it by clicking instead"
    else:
        page = await site_page(site)
        data = await extract(page)
    return compact(site, data, offset, links)


@server.tool()
@guard(90)
async def fetch_like(site: str, example_url: str, example_value: str, values: list[str]) -> str:
    """Read many pages of the same kind at once, after you reached ONE of them by clicking. Give that page's address
    (example_url), the value in it that identifies the record or page (example_value, e.g. a key or a page number
    that appears in the address), and the other values you want (values, at most 20). Each page is opened in a
    background tab of the same login and returned as text. Much faster than clicking to each one.
    A page that cannot be read this way comes back as "FAILED: <reason> - open it by clicking": then click to it
    instead, don't retry the same address. Only for reading; never for forms, gates, or actions."""
    example = clean_url(urljoin(SITES.get(site, "") + "/", example_url))
    await browser()
    known = visited[site] | {clean_url(p.url) for c in _browser.contexts for p in c.pages}
    if example not in known:
        return ("FAILED: reach one page of this kind by clicking first (or read it), then call fetch_like with its "
                "exact address")
    token = next((t for t in (example_value, quote(example_value, safe=""), quote(example_value)) if t in example),
                 None)
    if not token:
        return f"FAILED: {example_value!r} does not appear in {example}"
    if example.count(token) != 1:
        return f"FAILED: {example_value!r} appears {example.count(token)} times in the address: ambiguous"
    values = [str(v) for v in values][:20]
    urls = [example.replace(token, quote(v, safe="") if token != example_value else v) for v in values]
    reference, *results = await asyncio.gather(render(site, example), *(render(site, u) for u in urls))
    ref_len = len(reference.get("text") or "")
    ref_path = urlparse(example).path
    out = []
    for value, url, data in zip(values, urls, results):
        text = data.get("text") or ""
        reason = None
        if data.get("error"):
            reason = data["error"]
        elif data.get("status") and data["status"] >= 400:
            reason = f"HTTP {data['status']}"
        elif data.get("password"):
            reason = "a login page (session expired?)"
        elif urlparse(clean_url(data.get("url", ""))).path != urlparse(url).path and ref_path == urlparse(url).path:
            reason = f"redirected to {data.get('url')}"
        elif not re.search(r"(?<![\w-])" + re.escape(unquote(value)) + r"(?![\w-])", text.translate(ZERO_WIDTH), re.I):
            reason = f"the page does not show {value!r}"
        elif ref_len and len(text) < 0.4 * ref_len:
            reason = "much shorter than the example page"
        if reason:
            out.append(f"## {value}: FAILED: {reason} - open it by clicking")
        else:
            out.append(compact(site, data))
    return "\n\n".join(out)


# --- evidence ----------------------------------------------------------------------------------------------------------

KINDS: dict[str, type[BaseModel]] = {
    kind: typing.get_args(ev.Evidence.model_fields[kind].annotation)[0] for kind in ev._KEYS}
KEYS = dict(ev._KEYS)
ATOMIC = {"price_conditions"}

ATOMIC = {"price_conditions"}
NESTED_KEYS = {"requirements": "id", "price_conditions": "valid_from", "scales": "min_quantity"}
case: dict = {}
store: dict[str, dict[str, dict]] = {kind: {} for kind in KINDS}
picks: dict = {}
started = time.monotonic()


def nested_model(annotation):
    if isinstance(annotation, type) and issubclass(annotation, BaseModel):
        return annotation
    for arg in typing.get_args(annotation):
        found = nested_model(arg)
        if found:
            return found
    return None


def problems(model: type[BaseModel], data, path: str = "") -> list[str]:
    """Unknown field names (the schema would drop them silently) and numbers that need their format stated."""
    if not isinstance(data, dict):
        return []
    fields, out = model.model_fields, []
    for key, value in data.items():
        if key not in fields:
            near = difflib.get_close_matches(key, fields, n=1, cutoff=0.6)
            out.append(f"{path}{key}: unknown field" + (f" (did you mean {near[0]!r}?)" if near else "")
                       + f"; allowed: {', '.join(fields)}")
            continue
        sub = nested_model(fields[key].annotation)
        if sub and isinstance(value, list):
            for i, item in enumerate(value):
                out += problems(sub, item, f"{path}{key}[{i}].")
        elif sub:
            out += problems(sub, value, f"{path}{key}.")
        elif (isinstance(value, float) and re.fullmatch(r"-?\d+\.\d{3}", repr(value))) or (
                isinstance(value, str) and re.fullmatch(r"\s*-?\d{1,3}([.,]\d{3})+\s*", value)):
            out.append(f"{path}{key}: {value} is ambiguous (thousands separator or decimals?): send it as "
                       f'{{"raw": "<exactly as shown>", "format": "de" or "en"}}')
    return out


def numbers_from_raw(data):
    """{"raw": "1.234,56", "format": "de"} -> "1234.56", anywhere in a record."""
    if isinstance(data, dict):
        if set(data) <= {"raw", "format"} and "raw" in data:
            raw = str(data["raw"]).strip()
            fmt = str(data.get("format") or "").lower()[:2]
            m = re.search(r"-?\d[\d.,  ' ]*", raw)
            if not m:
                return raw
            return plain_number(m.group(0).strip(), fmt if fmt in ("de", "en") else "en")
        return {k: numbers_from_raw(v) for k, v in data.items()}
    if isinstance(data, list):
        return [numbers_from_raw(v) for v in data]
    return data


def empty(value) -> bool:
    return value is None or value == "" or value == [] or value == {} or (
        isinstance(value, str) and value.strip().lower() in ("unknown", "n/a", "none found"))


def merge_record(old, new):
    """Field by field: a later record adds and corrects values, but never wipes a known value with an empty one.
    Nested lists with keys (requirements, price conditions, scales) are merged per key."""
    if isinstance(old, dict) and isinstance(new, dict):
        out = dict(old)
        for key, value in new.items():
            if empty(value):
                continue
            if key in NESTED_KEYS and isinstance(old.get(key), list) and isinstance(value, list):
                k = NESTED_KEYS[key]
                rows = {str(r.get(k)): r for r in old[key] if isinstance(r, dict)}
                for r in value:
                    if isinstance(r, dict):
                        # a price condition is one unit: its prices only mean something with its own price unit,
                        # currency and scales, so a resent condition replaces the old one instead of mixing with it
                        rows[str(r.get(k))] = r if key in ATOMIC else merge_record(rows.get(str(r.get(k))), r)
                out[key] = list(rows.values())
            else:
                out[key] = merge_record(old.get(key), value)
        return out
    return new


import contextlib
import fcntl


@contextlib.contextmanager
def shared_store():
    """Several sessions (one per website) record into the same store at once: reload it under a file lock first."""
    with open(str(STORE) + ".lock", "w") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            load()
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


def save() -> None:
    STORE.write_text(json.dumps({"case": case, "picks": picks, **{k: list(v.values()) for k, v in store.items()}},
                                ensure_ascii=False, indent=1, default=str))


def evidence() -> ev.Evidence:
    return ev.Evidence.model_validate({"case": case, "picks": picks, **{k: list(v.values()) for k, v in store.items()}})


SCHEMAS = "\n".join(f"- {kind} (one record per {KEYS[kind]}): "
                    + json.dumps(model.model_json_schema(), ensure_ascii=False, separators=(",", ":"))
                    for kind, model in KINDS.items())
CASE_SCHEMA = json.dumps(ev.Case.model_json_schema(), ensure_ascii=False, separators=(",", ":"))


@server.tool(description=(
    "Save evidence records of one kind as soon as you have read them (several records per call is best). A record "
    "with the same key as an earlier one is merged field by field: send only what is new or corrected; empty values "
    "never erase known ones. Use exactly the schema's field names (unknown names are rejected with the nearest "
    "correct one). Numbers: never convert them yourself; if the page writes a number with thousands separators or a "
    'decimal comma, send {"raw": "<exactly as shown>", "format": "de"} (de: 1.234,5) or "en" (en: 1,234.5). '
    "kind 'case' takes one record with the case fields. Invalid records come back with the reason: fix and resend.\n"
    f"- case: {CASE_SCHEMA}\n" + SCHEMAS))
def record(kind: str, records: list[dict]) -> str:
    with shared_store():
        return _record(kind, records)


def _record(kind: str, records: list[dict]) -> str:
    if kind == "case":
        update = {k: v for r in records for k, v in numbers_from_raw(r).items() if not empty(v)}
        bad = problems(ev.Case, update)
        if bad:
            return "Not saved: " + "; ".join(bad)
        case.update(update)
        save()
        return f"case: {case}"
    if kind == "picks":
        picks.update({k: v for r in records for k, v in r.items() if not empty(v)})
        save()
        return "picks saved"
    if kind not in KINDS:
        return f"Unknown kind {kind!r}; use one of case, {', '.join(KINDS)}"
    saved, errors = 0, []
    for n, raw in enumerate(records):
        bad = problems(KINDS[kind], raw)
        if bad:
            errors.append(f"record {n}: " + "; ".join(bad))
            continue
        key = str(raw.get(KEYS[kind]) or "")
        if not key:
            errors.append(f"record {n}: {KEYS[kind]} is required")
            continue
        merged = merge_record(store[kind].get(key), numbers_from_raw(raw))
        try:
            clean = KINDS[kind].model_validate(merged).model_dump(mode="json", exclude_none=True)
        except ValidationError as error:
            errors.append(f"record {n} ({key}): " + "; ".join(
                f"{'.'.join(map(str, e['loc']))}: {e['msg']}" for e in error.errors(include_url=False)))
            continue
        store[kind][key] = merge_record(store[kind].get(key), clean)
        saved += 1
    save()
    return (f"Saved {saved} {kind} ({len(store[kind])} in total)." + (f" NOT saved: {errors}" if errors else "")
            + unstructured_note(kind, records))


async def keep_alive(site: str) -> None:
    """While a session waits, read its current page again in a background tab, so a short login timeout does not
    end the session (the same as a user who keeps the page open and refreshes it)."""
    try:
        page = await site_page(site)
        if page.url.startswith("http"):
            await asyncio.wait_for(render(site, clean_url(page.url)), 15)
    except Exception:  # noqa: BLE001 - only a courtesy
        pass


STRUCTURED = {"qa": ("quantity_changes", "amendments", "withdraws", "assignments"),
              "messages": ("discount_percent", "min_order_value_eur", "condition_rules", "metal_index_rates",
                           "technical_releases", "packaging_tariffs", "delivery_commitments", "fx_rates",
                           "setup_pools", "bonus_plans")}


def unstructured_note(kind: str, records: list[dict]) -> str:
    """Code reads only the structured fields, never the text: point out records that carry none of them."""
    if kind not in STRUCTURED:
        return ""
    bare = [str(r.get(KEYS[kind])) for r in records if isinstance(r, dict)
            and (kind != "messages" or r.get("kind") not in (None, "other", "signing_tan"))
            and not any(not empty(r.get(f)) for f in STRUCTURED[kind])]
    if not bare:
        return ""
    fields = ", ".join(STRUCTURED[kind])
    return (f" NOTE: {len(bare)} of these ({', '.join(bare[:12])}) have none of the fields {fields}. The text is "
            f"never evaluated: if a record changes a quantity, an attribute, withdraws an earlier record, assigns a key "
            f"or states values, put that into those fields (send the record again with them).")


ACTIVE = Path(os.environ.get("ACTIVE_PATH", "active.json"))


def others() -> str:
    """The other sessions still researching (main.py keeps the list)."""
    try:
        names = [n for n in json.loads(ACTIVE.read_text()) if n != os.environ.get("SESSION_SITE")]
    except (OSError, ValueError):
        return ""
    return ("\nStill researching in parallel: " + ", ".join(names)) if names else "\nNo other session is researching."


@server.tool()
async def gaps(wait_s: int = 0) -> str:
    """What the bid rules still miss in the recorded evidence, as questions to answer next (and which positions
    can already be priced). Call it when you think you are done, and after answering the questions.
    wait_s (at most 90): first wait until another session records something new (or the time is up)."""
    if wait_s > 0:
        before = STORE.stat().st_mtime if STORE.exists() else 0
        end = time.monotonic() + min(wait_s, 90)
        own = os.environ.get("SESSION_SITE")
        touched = time.monotonic()
        while time.monotonic() < end:
            await asyncio.sleep(2)

            if (STORE.stat().st_mtime if STORE.exists() else 0) != before:
                await asyncio.sleep(3)
                break
    with shared_store():
        return _gaps() + others()


def norm_key(value) -> str:
    return re.sub(r"\s+", "", str(value or "").translate(ZERO_WIDTH)).upper()


def open_keys(e: ev.Evidence) -> list[str]:
    """Every key the evidence already names that no record resolves yet, whatever stage the rules are at: so each
    website can work on it now instead of waiting for the rules to get there."""
    out: list[str] = []
    searched = {norm_key(s.catalog_group): s for s in e.erp_searches}
    recorded = {norm_key(m.number) for m in e.materials}
    groups: dict[str, list[str]] = {}
    for rev in e.revisions:
        for req in rev.requirements:
            group = norm_key(req.catalog_group)
            if group and (group not in searched or not searched[group].complete):
                groups.setdefault(req.catalog_group, []).append(f"{req.id} of revision {rev.id}")
    for group, where in groups.items():
        out.append(f"Search the ERP for catalogue group {group} (named by requirement {', '.join(where[:4])}); open "
                   "every listed material, record them and the search.")
    for s in e.erp_searches:
        for number in s.material_numbers:
            if norm_key(number) not in recorded:
                out.append(f"Open ERP material {number} (listed for group {s.catalog_group}) and record it.")
    defined: dict[str, set[str]] = defaultdict(set)
    for m in e.messages:
        for field, entries in (("condition_group", m.condition_rules), ("packaging_tariff", m.packaging_tariffs),
                               ("delivery_commitment", m.delivery_commitments), ("setup_pool", m.setup_pools),
                               ("bonus_plan", m.bonus_plans), ("end_reserve", m.technical_releases),
                               ("fx", m.fx_rates)):
            defined[field] |= {norm_key(x.key) for x in entries}
        defined["metal_index"] |= {norm_key(x.code) for x in m.metal_index_rates}
    asked: set[tuple[str, str]] = set()

    def need(field: str, key, what: str):
        k = norm_key(key)
        if k and k not in defined[field] and (field, k) not in asked:
            asked.add((field, k))
            out.append(f"Find the latest mail for this exact tender reference that defines {what} {key} (see the "
                       "brief's rules for its sender and subject; check inbox and archive) and record it.")
    for qa in e.qa:
        for a in qa.assignments:
            need("condition_group", a.condition_group, "condition group (Konditionsgruppe)")
            need("packaging_tariff", a.packaging_tariff, "packaging tariff")
            need("delivery_commitment", a.delivery_commitment, "delivery commitment")
            need("setup_pool", a.setup_pool, "setup pool")
            need("bonus_plan", a.bonus_plan, "project bonus plan")
    for rev in e.revisions:
        for req in rev.requirements:
            need("end_reserve", req.end_reserve_key, f"the end reserve (technical release) for revision {rev.id}, key")
    for m in e.materials:
        need("metal_index", m.metal_index, "metal index rates for code")
        for c in m.price_conditions:
            if (c.currency or "EUR").upper() != "EUR":
                need("fx", c.fx_key, f"the {c.currency} exchange rate, key")
    if not any(m.kind == "discount_approval" for m in e.messages):
        out.append("Find the sales director's discount approvals for this exact tender reference (inbox and "
                   "archive, every page) and record them, also superseded ones.")
    return out


def implausible_prices(e: ev.Evidence, factor: Decimal = Decimal(20)) -> list[str]:
    """Per-piece prices that are far off the same material's other conditions or its catalogue group's other
    materials (same currency): the typical result of a misread thousands separator or price unit."""
    rows = []   # (material, group, condition, currency, per-piece price of the smallest scale)
    for m in e.materials:
        for c in m.price_conditions:
            if not c.scales or not c.price_unit:
                continue
            first = min(c.scales, key=lambda x: x.min_quantity)
            if first.price and first.price > 0:
                rows.append((m.number, norm_key(m.catalog_group), c, (c.currency or "EUR").upper(),
                             Decimal(first.price) / Decimal(c.price_unit)))
    out = []
    for number, group, c, cur, unit in rows:
        peers = [u for n, g, _, cu, u in rows if cu == cur and (n == number or (group and g == group))
                 and not (n == number and _ is c)]
        if not peers:
            continue
        mid = sorted(peers)[len(peers) // 2]
        if unit > mid * factor or unit * factor < mid:
            out.append(f"Re-read material {number}'s price condition valid from {c.valid_from} exactly as the page "
                       f"shows it: it gives {unit:.4f} {cur} per piece, its other conditions/group give about "
                       f"{mid:.4f}. Check thousands separators vs decimals (a marker like (en-US) means a comma "
                       f"separates thousands) and the price unit, then record it again.")
    return out


def _gaps() -> str:
    if not case.get("tender_reference") or not case.get("scenario_date"):
        return "Record the case first (kind 'case': tender reference and scenario date from the brief, the domain " \
               "of the bidder's own mailbox)."
    try:
        resolution = resolve(evidence())
    except ValidationError as error:
        return "The evidence does not validate: " + "; ".join(
            f"{'.'.join(map(str, e['loc']))}: {e['msg']}" for e in error.errors(include_url=False)[:10])
    except Exception as error:  # noqa: BLE001
        return f"The rules could not run: {error!r}"
    lines = [f"- {g.question}" for g in resolution.gaps] + [f"- {q}" for q in implausible_prices(evidence())]
    priced = len((resolution.answer or {}).get("positions") or [])
    head = f"{priced} positions can be priced now."
    text = head + ("\nStill missing:\n" + "\n".join(lines) if lines else "\nNothing is missing.")
    if lines:
        asked = {g.question for g in resolution.gaps}
        extra = [q for q in open_keys(evidence()) if q not in asked]
        if extra:
            text += "\nAlso open already (work on those your website holds, now):\n" + "\n".join(
                f"- {q}" for q in extra[:40])
    return text


@server.tool()
def peek(kind: str = "") -> str:
    """What all sessions have recorded so far (the other websites' researchers too), compactly: one line per
    record. Use it to start on your website with what the others found (references, groups, keys, materials) before
    `gaps` asks for it. kind: one of the record kinds, or empty for a count per kind."""
    with shared_store():
        if not kind:
            return "case: " + json.dumps(case, ensure_ascii=False) + "\n" + "\n".join(
                f"{k}: {len(v)} records" for k, v in store.items())
        if kind not in store:
            return f"Unknown kind {kind!r}; use one of {', '.join(store)}"
        rows = [json.dumps(r, ensure_ascii=False, separators=(",", ":"))[:600] for r in store[kind].values()]
        return f"{kind}: {len(rows)} records\n" + "\n".join(rows)[:12000]


def load() -> None:
    """A follow-up session continues on the evidence the earlier ones saved."""
    if STORE.exists():
        try:
            data = json.loads(STORE.read_text())
        except ValueError:
            return
        case.update(data.get("case") or {})
        picks.update(data.get("picks") or {})
        for kind in KINDS:
            store[kind] = {str(r.get(KEYS[kind])): r for r in data.get(kind) or []}


load()

if __name__ == "__main__":
    server.run()

"""Generic form tools for a model that enters a computed bid into an unknown web form and signs it (MCP, stdio).

Nothing here knows a website. Pages are described as fields (label, value, options), buttons, links, messages and
dialogs with short ids; ids never repeat, so an id from an older look is rejected instead of hitting another field.
`act` runs a whole form step in one call; every value is read back (numbers compared as numbers, in any format).
Browser confirm dialogs are dismissed, except by `sign`, which first checks in code that the page shows every value
of the bid and then reports RECEIPT / ERROR / NO-CHANGE.

Environment:
  FORM_BROWSERS  {"<siteId>": "<CDP URL>", ...}   the browser each site is worked in
  ACCESS_JSON    the run's access list [{siteId, url, credentials}], for `login`
  SIGN_LOG       optional JSON-lines file: every sign attempt with its check and outcome (read by the harness)
"""
