ENDPOINTS: dict[str, str] = json.loads(os.environ.get("FORM_BROWSERS", "{}"))
ACCESS = {a["siteId"]: a for a in json.loads(os.environ.get("ACCESS_JSON", "[]"))}
SIGN_LOG = os.environ.get("SIGN_LOG")
ACTION_MS = 5000
server = MCPServer("form", instructions="Look at, fill in and sign web forms: " + ", ".join(ENDPOINTS))

_pw = None
_pages: dict = {}
_ids: dict = {}            # site -> {"F31": frame}
_counter: dict = {}        # site -> next id number (never reused)
_dialog: dict = {}         # site -> {"accept": bool, "seen": [...]}
_new_tabs: dict = {}       # site -> [urls of tabs the site opened]

SCAN = r"""(start) => {
  const clean = t => (t || '').replace(/[​-‍⁠﻿­]/g, '').replace(/\s+/g, ' ').trim();
  const visible = e => { const r = e.getBoundingClientRect(), s = getComputedStyle(e);
    return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0'; };
  const labelOf = e => {
    const a = e.getAttribute('aria-label'); if (a) return clean(a);
    const lb = e.getAttribute('aria-labelledby');
    if (lb) return clean(lb.split(/\s+/).map(i => (document.getElementById(i) || {}).innerText || '').join(' '));
    if (e.labels && e.labels.length) return clean(Array.from(e.labels).map(l => {
      const c = l.cloneNode(true); c.querySelectorAll('select, input, textarea, option').forEach(x => x.remove());
      return c.textContent; }).join(' '));
    if (e.placeholder) return clean(e.placeholder);
    let p = e.parentElement;
    for (let i = 0; i < 3 && p; i++, p = p.parentElement) { const t = clean(p.innerText); if (t && t.length < 90) return t; }
    return clean(e.name || e.id || '');
  };
  let n = start;
  const fields = [], buttons = [], links = [], messages = [], dialogs = [];
  const mark = (e, prefix) => { const id = prefix + (n++); e.setAttribute('data-ff', id); return id; };
  for (const e of document.querySelectorAll('[data-ff]')) e.removeAttribute('data-ff');
  const fieldSel = 'input:not([type=hidden]):not([type=submit]):not([type=button]):not([type=reset]):not([type=image]),' +
    'select, textarea, [role=combobox], [role=checkbox], [role=radio], [role=switch], [role=slider], [contenteditable=true]';
  for (const e of document.querySelectorAll(fieldSel)) {
    if (!visible(e) && !(e.type === 'checkbox' || e.type === 'radio')) continue;
    if ((e.type === 'checkbox' || e.type === 'radio') && !visible(e) && !(e.labels && e.labels[0] && visible(e.labels[0]))) continue;
    const type = e.tagName === 'SELECT' ? 'select' : e.tagName === 'TEXTAREA' ? 'textarea'
      : (e.getAttribute('role') && e.tagName !== 'INPUT') ? e.getAttribute('role') : (e.type || 'text');
    let value;
    if (type === 'checkbox' || type === 'radio') value = e.checked ? 'on' : 'off';
    else if (type === 'select') value = clean((e.selectedOptions[0] || {}).text || '');
    else if (e.isContentEditable) value = clean(e.innerText);
    else value = e.value || e.getAttribute('aria-valuenow') || '';
    const f = { id: mark(e, 'F'), type, label: labelOf(e), value };
    if (type === 'select') f.options = Array.from(e.options).map(o => clean(o.text)).slice(0, 40);
    if (type === 'radio' && e.name) f.group = e.name;
    if (e.disabled || e.getAttribute('aria-disabled') === 'true') f.disabled = true;
    if (e.required || e.getAttribute('aria-required') === 'true') f.required = true;
    if (e.getAttribute('aria-invalid') === 'true') f.invalid = true;
    fields.push(f);
  }
  const btnSel = 'button, input[type=submit], input[type=button], [role=button], [role=menuitem], [role=tab], summary';
  for (const e of document.querySelectorAll(btnSel)) {
    if (!visible(e)) continue;
    const b = { id: mark(e, 'B'), text: clean(e.innerText || e.value || e.getAttribute('aria-label') || e.title) };
    if (e.disabled || e.getAttribute('aria-disabled') === 'true') b.disabled = true;
    buttons.push(b);
  }
  for (const e of document.querySelectorAll('a[href]')) {
    if (!visible(e) || e.hasAttribute('data-ff')) continue;
    const t = clean(e.innerText || e.getAttribute('aria-label') || e.title);
    if (!t) continue;
    links.push({ id: mark(e, 'L'), text: t.slice(0, 80), href: e.getAttribute('href').slice(0, 100) });
  }
  const msgSel = '[role=alert], [role=status], [aria-live], .error, .errors, .alert, .warning, .notice, .invalid-feedback, ' +
    '[class*=error], [class*=fehler], [class*=message], [class*=hinweis], .toast';
  const seen = new Set();
  for (const e of document.querySelectorAll(msgSel)) {
    if (!visible(e)) continue;
    const t = clean(e.innerText); if (!t || t.length > 400 || seen.has(t)) continue;
    seen.add(t); messages.push(t);
  }
  for (const e of document.querySelectorAll('dialog[open], [role=dialog], [role=alertdialog], [aria-modal=true]')) {
    if (!visible(e)) continue;
    dialogs.push(clean(e.innerText).slice(0, 400));
  }
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, legend')).filter(visible).map(h => clean(h.innerText)).filter(Boolean).slice(0, 8);
  const password = Array.from(document.querySelectorAll('input[type=password]')).some(visible);
  return { next: n, fields, buttons, links, messages, dialogs, headings, password,
           text: clean(document.body ? document.body.innerText : '') };
}"""




def host(url: str) -> str:
    return urlparse(url).netloc


async def page_of(site: str):
    global _pw
    if site not in ENDPOINTS:
        raise ValueError(f"Unknown site {site!r}; known: {', '.join(ENDPOINTS)}")
    page = _pages.get(site)
    if page is not None and not page.is_closed():
        return page
    _pw = _pw or await async_playwright().start()
    browser = await _pw.chromium.connect_over_cdp(ENDPOINTS[site])
    context = browser.contexts[0] if browser.contexts else await browser.new_context()
    want = host(ACCESS.get(site, {}).get("url", ""))
    pages = [p for p in context.pages if want and host(p.url) == want]
    page = pages[-1] if pages else (context.pages[0] if context.pages and context.pages[0].url in ("about:blank", "")
                                    else await context.new_page())
    if not pages and want:
        await page.goto(ACCESS[site]["url"], wait_until="commit", timeout=15000)
    _dialog[site] = {"accept": False, "seen": []}
    _new_tabs.setdefault(site, [])
    context.on("page", lambda new: _new_tabs[site].append(new))
    _pages[site] = page
    attach(site, page)
    return page


def attach(site: str, page) -> None:
    page.set_default_timeout(ACTION_MS)
    page.set_default_navigation_timeout(15000)

    async def on_dialog(dialog):
        state = _dialog[site]
        accept = state["accept"] or dialog.type in ("alert", "beforeunload")
        state["seen"].append(f"browser {dialog.type} dialog \"{dialog.message}\" -> {'accepted' if accept else 'dismissed'}")
        await (dialog.accept() if accept else dialog.dismiss())
    page.on("dialog", on_dialog)


async def settle(page) -> None:
    try:  # never wait for "load"/"networkidle": some pages never finish loading
        await page.wait_for_load_state("domcontentloaded", timeout=3000)
    except PlaywrightError:
        pass
    await page.wait_for_timeout(250)


async def scan(site: str) -> dict:
    page = await page_of(site)
    await settle(page)
    n = _counter.get(site, 1)
    ids, merged = {}, {"fields": [], "buttons": [], "links": [], "messages": [], "dialogs": [], "headings": [],
                       "password": False, "text": []}
    for frame in page.frames:
        try:
            r = await asyncio.wait_for(frame.evaluate(SCAN, n), 8)
        except (PlaywrightError, asyncio.TimeoutError):
            continue
        n = r["next"]
        for kind in ("fields", "buttons", "links"):
            for item in r[kind]:
                ids[item["id"]] = frame
            merged[kind] += r[kind]
        for kind in ("messages", "dialogs", "headings"):
            merged[kind] += [x for x in r[kind] if x not in merged[kind]]
        merged["password"] = merged["password"] or r["password"]
        if r["text"]:
            merged["text"].append(r["text"])
    _counter[site] = n
    _ids[site] = ids
    merged["url"] = page.url
    merged["text"] = "\n".join(merged["text"])
    tabs = [t for t in _new_tabs.get(site, []) if not t.is_closed()]
    merged["new_tabs"] = [t.url for t in tabs]
    return merged


def render(s: dict, text_chars: int = 300) -> str:
    out = [f"URL: {s['url']}"]
    if s["headings"]:
        out.append("Headings: " + " | ".join(h[:80] for h in s["headings"]))
    if s["password"]:
        out.append("A password field is visible: a login page (or the session expired: use login).")
    if s.get("new_tabs"):

    if s["headings"]:
        out.append("Headings: " + " | ".join(h[:80] for h in s["headings"]))
    if s["password"]:
        out.append("A password field is visible: a login page (or the session expired: use login).")
    if s.get("new_tabs"):
        out.append("The site opened other tabs (not followed): " + ", ".join(s["new_tabs"][:3]))
    out += ["Open dialog/overlay: " + d[:300] for d in s["dialogs"]]
    out += ["Message: " + m[:300] for m in s["messages"]]
    if s["fields"]:
        out.append("Fields:")
        for f in s["fields"]:
            flags = " ".join(k for k in ("required", "disabled", "invalid") if f.get(k))
            line = f"  {f['id']} {f['type']} \"{f['label'][:60]}\" = \"{f['value'][:50]}\"" + (f" [{flags}]" if flags else "")
            if f.get("options"):
                line += " options: " + " | ".join(o[:40] for o in f["options"][:25])
            out.append(line)
    if s["buttons"]:
        out.append("Buttons: " + ", ".join(f"{b['id']} \"{b['text'][:40]}\"" + (" [disabled]" if b.get("disabled") else "")
                                         for b in s["buttons"][:40]))
    if s["links"]:
        out.append("Links: " + ", ".join(f"{l['id']} \"{l['text'][:40]}\"" for l in s["links"][:25])
                   + (f" ... {len(s['links']) - 25} more" if len(s["links"]) > 25 else ""))
    if text_chars:
        out.append("Text: " + s["text"][:text_chars] + (" ..." if len(s["text"]) > text_chars else ""))
    return "\n".join(out)


async def locate(site: str, target: str, kinds: str = "FBL"):
    target = target.strip()
    if re.fullmatch(r"[FBL]\d+", target):
        ids = _ids.get(site) or {}
        if target not in ids:
            raise ValueError(f"No element {target} on the current page (ids from older looks are not valid)")
        return ids[target].locator(f'[data-ff="{target}"]'), target
    s = await scan(site)
    want = norm(target)
    pool = ([("F", f["id"], f["label"]) for f in s["fields"]] + [("B", b["id"], b["text"]) for b in s["buttons"]]
            + [("L", l["id"], l["text"]) for l in s["links"]])
    pool = [p for p in pool if p[0] in kinds]
    hits = [p for p in pool if norm(p[2]) == want] or [p for p in pool if want in norm(p[2])]
    if len(hits) != 1:
        raise ValueError(f"{len(hits)} elements match {target!r}: use an id ("
                         + ", ".join(f"{h[1]} {h[2][:40]!r}" for h in hits[:8]) + ")")
    return _ids[site][hits[0][1]].locator(f'[data-ff="{hits[0][1]}"]'), hits[0][1]


def norm(v: str) -> str:
    return re.sub(r"\s+", " ", (v or "").replace("\u00a0", " ")).strip().lower()


def as_number(text: str) -> Decimal | None:
    """'1.234,56' / '1,234.56' / '1234.56' / '1234,56' -> 1234.56; None if it is not one number."""
    t = re.sub(r"[\s\u00a0\u202f\'%€$]|EUR|USD", "", text or "", flags=re.I)
    if not re.fullmatch(r"-?[\d.,]+", t) or not re.search(r"\d", t):
        return None
    if "," in t and "." in t:
        dec = "," if t.rfind(",") > t.rfind(".") else "."
        t = t.replace("." if dec == "," else ",", "").replace(",", ".")
    elif t.count(",") == 1 and len(t.split(",")[1]) != 3:
        t = t.replace(",", ".")
    elif t.count(".") == 1 and len(t.split(".")[1]) != 3:
        pass
    elif "," in t or "." in t:
        t = t.replace(",", "").replace(".", "")  # only grouping separators
    try:
        return Decimal(t)
    except InvalidOperation:
        return None


def same_value(got: str, want: str) -> bool:
    if norm(got) == norm(want):
        return True
    a, b = as_number(got), as_number(want)
    return a is not None and b is not None and a == b


async def set_value(loc, value: str) -> str:
    info = await loc.evaluate("e => ({tag: e.tagName, type: e.type || e.getAttribute('role') || '', "
                              "editable: e.isContentEditable})")
    kind = (info["type"] or "").lower()
    if info["tag"] != "SELECT" and kind not in ("checkbox", "radio", "switch") and not await loc.is_editable():
        raise ValueError("not editable: it may unlock after another field or button, or sit in a collapsed section")
    if info["tag"] == "SELECT":
        options = await loc.evaluate("e => Array.from(e.options).map(o => ({text: o.text.trim(), value: o.value}))")
        exact = [o for o in options if norm(o["text"]) == norm(value) or norm(o["value"]) == norm(value)]
        pick = exact or [o for o in options if norm(value) in norm(o["text"])]
        if len(pick) != 1:
            raise ValueError(f"option {value!r} not found unambiguously; options: {[o['text'] for o in options][:25]}")
        await loc.select_option(value=pick[0]["value"])
        return await loc.evaluate("e => (e.selectedOptions[0] || {}).text || ''")
    if kind in ("checkbox", "radio", "switch"):
        on = norm(value) in ("on", "true", "yes", "1", "x", "checked")
        await loc.set_checked(on, force=True)
        return "on" if await loc.is_checked() else "off"
    if info["editable"]:
        await loc.click()
        await loc.press("ControlOrMeta+a")
        await loc.type(value)
        return await loc.inner_text()
    await loc.fill(value)
    if kind == "combobox" or await loc.get_attribute("list"):
        await loc.press("Enter")
    return await loc.input_value()


def tool_guard(seconds: float):
    def wrap(fn):
        @functools.wraps(fn)
        async def inner(*args, **kwargs):
            try:
                return await asyncio.wait_for(fn(*args, **kwargs), seconds)
            except asyncio.TimeoutError:
                return f"FAILED: no result within {seconds:.0f} s; look at the page again"
            except Exception as error:  # noqa: BLE001
                return f"FAILED: {type(error).__name__}: {str(error).splitlines()[0][:200] if str(error) else ''}"
        return inner
    return wrap


@server.tool()
@tool_guard(25)
async def look(site: str, text_chars: int = 300) -> str:
    """The current page of a site: headings, messages, open dialogs, fields (id, type, label, value, options),
    buttons, links and the start of the visible text (text_chars; more to read further). Ids are unique: always use
    the ids of the latest look."""
    return render(await scan(site), text_chars)


@server.tool()
@tool_guard(25)
async def goto(site: str, url: str) -> str:
    """Open an address in the site's tab (for the site's start page or a link you saw; never to skip form steps)."""
    page = await page_of(site)
    await page.goto(url, wait_until="commit")
    return render(await scan(site))


@server.tool()
@tool_guard(40)
async def login(site: str) -> str:
    """Log in to the site with the run's credentials: fills the visible username and password fields and submits.
    Use it whenever a login page appears (also when a session expired in the middle of a form)."""
    creds = (ACCESS.get(site) or {}).get("credentials") or {}
    page = await page_of(site)
    s = await scan(site)
    pw = [f for f in s["fields"] if f["type"] == "password"]
    if not pw:
        return "No password field on this page.\n\n" + render(s)
    users = [f for f in s["fields"] if f["type"] in ("text", "email") and not f.get("disabled")]
    if users:
        await (await locate(site, users[0]["id"], "F"))[0].fill(creds.get("username", ""))
    loc = (await locate(site, pw[0]["id"], "F"))[0]
    await loc.fill(creds.get("password", ""))
    await loc.press("Enter")
    await page.wait_for_timeout(1200)
    return "Submitted the login.\n\n" + render(await scan(site))


async def run_step(site: str, step: dict) -> tuple[str, bool]:
    """One step of act: (report line, ok)."""
    (verb, arg), = step.items()
    if verb == "fill":
        lines, ok = [], True
        for target, value in arg.items():
            try:
                loc, eid = await locate(site, target, "F")
                got = await set_value(loc, str(value))
                good = same_value(got, str(value))
                ok &= good
                lines.append(f"{eid} = {got!r}" + ("" if good else f"  <-- MISMATCH, wanted {value!r}"))
            except (PlaywrightError, ValueError) as e:
                ok = False
                lines.append(f"{target}: FAILED: {str(e).splitlines()[0][:200]}")
        return "\n".join(lines), ok
    if verb in ("click", "check", "uncheck"):
        try:
            loc, eid = await locate(site, str(arg), "BLF" if verb == "click" else "F")
            if verb == "click":
                await loc.click()
            else:
                await loc.set_checked(verb == "check", force=True)
            await (await page_of(site)).wait_for_timeout(400)
            return f"{verb} {eid}", True
        except (PlaywrightError, ValueError) as e:
            msg = str(e)
            blocker = next((l.strip() for l in msg.splitlines() if "intercepts pointer events" in l), None)
            return (f"{verb} {arg}: " + ("BLOCKED by " + blocker[:200] + " (close it first)" if blocker
                                         else "FAILED: " + msg.splitlines()[0][:200])), False
    if verb == "press":
        await (await page_of(site)).keyboard.press(str(arg))
        return f"pressed {arg}", True
    if verb == "drag_right":
        return await drag(site, str(arg)), True
    return f"unknown step {verb!r} (use fill, click, check, uncheck, press, drag_right)", False


@server.tool()
@tool_guard(45)
async def act(site: str, steps: list[dict], text_chars: int = 300) -> str:
    """Do a whole form step in one call, in order, like a user: steps = [{"fill": {"<label or id>": "value", ...}},
    {"check": "<label or id>"}, {"uncheck": ...}, {"click": "<button/link text or id>"}, {"press": "Enter"},
    {"drag_right": "<slider handle>"}]. Fields are found by their label (or an id from the latest look); selects
    take the option text, checkboxes on/off. Every filled value is read back (numbers compare as numbers). Stops at
    the first failure, mismatch, login page or dialog, and returns what happened plus the page. Confirm dialogs are
    dismissed here: the final binding confirmation is done with `sign`."""
    page = await page_of(site)
    state = _dialog[site]
    state["accept"], state["seen"] = False, []
    before, report = page.url, []
    for step in steps:
        if not isinstance(step, dict) or len(step) != 1:
            report.append(f"bad step {step!r}")
            break
        line, ok = await run_step(site, step)
        report.append(line)
        if state["seen"]:
            report += state["seen"]
            state["seen"] = []
            break
        if not ok:
            break
    s = await scan(site)
    if s["url"] != before:
        report.append(f"The page changed to {s['url']}.")
    return "\n".join(report) + "\n\n" + render(s, text_chars)


async def drag(site: str, target: str) -> str:
    page = await page_of(site)
    loc, eid = await locate(site, target, "FBL")
    box = await loc.bounding_box()
    track = await loc.evaluate("""e => { let p = e.parentElement;
        while (p && p.getBoundingClientRect().width < e.getBoundingClientRect().width * 2) p = p.parentElement;
        const r = (p || e).getBoundingClientRect(); return {x: r.x, width: r.width}; }""")
    x, y = box["x"] + box["width"] / 2, box["y"] + box["height"] / 2
    end = track["x"] + track["width"] - 2
    await page.mouse.move(x, y)
    await page.mouse.down()
    for i in range(1, 19):
        await page.mouse.move(x + (end - x) * i / 18, y + (1 if i % 2 else -1))
        await page.wait_for_timeout(25)
    await page.mouse.up()
    await page.wait_for_timeout(500)
    return f"dragged {eid} to the right end"


def variants(value: str) -> list[str]:
    """How a page may write a number: 9876.54 -> 9.876,54 / 9,876.54 / 9876,54 / 9876.54."""
    d = as_number(value)
    if d is None:
        return [value]
    q = f"{d:.2f}" if d != d.to_integral() or "." in value else f"{d:f}"
    whole, _, frac = q.partition(".")
    grouped = f"{int(whole):,}"
    out = {q, f"{grouped}.{frac}" if frac else grouped, (grouped.replace(",", ".") + ("," + frac if frac else "")),
           whole + ("," + frac if frac else "")}
    return sorted(out)


def shows(text: str, value: str) -> bool:
    flat = re.sub(r"[\s\u00a0\u202f]", "", text)
    return any(re.search(r"(?<![\d.,])" + re.escape(v) + r"(?![\d])", flat) for v in variants(value))

